// ============================================================================
// FRENCH (FR), GERMAN (DE), ITALIAN (IT), PORTUGUESE PLE (PT)
// Compact high-fidelity builders for each language's 12 specialized units
// ============================================================================

interface CompactUnitSeed {
  trackId: SpecializedTrackId;
  unitIndex: 1 | 2 | 3;
  level: CEFRLevel;
  titlePt: string;
  titleEn: string;
  subtitle: string;
  coverConceptId: string;
  tipCategory: TipCategory;
  tipTitle: string;
  tipSummary: string;
  tipDetails: string;
  exampleTarget: string;
  examplePt: string;
  vocab: Array<[word: string, translation: string, ipa: string, exTarget: string, exPt: string, conceptId: string]>;
  audioText: string;
  listenQ: string;
  listenRight: string;
  listenWrong1: string;
  listenWrong2: string;
  listenWrong3: string;
  readText: string;
  readQ: string;
  readRight: string;
  readWrong1: string;
  readWrong2: string;
  readWrong3: string;
  speakTarget: string;
  speakPt: string;
  speakIpa: string;
  speakHint: string;
  writePrompt: string;
  writeModel: string;
  speakerLabel: string;
}

function hydrateCompactSpecs(lang: LanguageCode, seeds: CompactUnitSeed[]): RawUnitSpec[] {
  return seeds.map((s) => ({
    trackId: s.trackId,
    unitIndex: s.unitIndex,
    level: s.level,
    titlePt: s.titlePt,
    titleEn: s.titleEn,
    subtitle: s.subtitle,
    estimatedMinutes: s.level === 'C1' ? 15 : s.level === 'B2' ? 14 : 12,
    coverConceptId: s.coverConceptId,
    tipCategory: s.tipCategory,
    tipTitle: s.tipTitle,
    tipSummary: s.tipSummary,
    tipDetails: s.tipDetails,
    tipExamples: [{ en: s.exampleTarget, pt: s.examplePt }],
    vocab: s.vocab.map(([word, translation, ipa, exampleTarget, examplePt, visualConceptId]) => ({
      word,
      translation,
      ipa,
      exampleTarget,
      examplePt,
      visualConceptId,
    })),
    listening: {
      speakerLabel: s.speakerLabel,
      contextPt: lang === 'pt' ? 'Listen to the domain briefing and answer.' : 'Ouça o briefing técnico e responda.',
      audioText: s.audioText,
      question: s.listenQ,
      options: [s.listenRight, s.listenWrong1, s.listenWrong2, s.listenWrong3],
      correctIndex: 0,
      explanation: s.listenRight,
      hintTip: s.tipSummary,
    },
    reading: {
      title: s.titlePt,
      format: 'article',
      text: s.readText,
      question: s.readQ,
      options: [s.readRight, s.readWrong1, s.readWrong2, s.readWrong3],
      correctIndex: 0,
      explanation: s.readRight,
      hintTip: s.tipSummary,
    },
    speaking: {
      promptPt: lang === 'pt' ? 'Read the specialized statement aloud.' : 'Pronuncie a declaração especializada em voz alta.',
      targetSentence: s.speakTarget,
      translationPt: s.speakPt,
      ipa: s.speakIpa,
      brPhoneticHint: s.speakHint,
      focusTip: s.tipTitle,
    },
    writing: {
      promptPt: s.writePrompt,
      scenarioPt: s.subtitle,
      minWords: 16,
      checklist: [
        { label: lang === 'pt' ? 'Use specialized terms' : 'Usar léxico técnico', keywords: s.vocab.slice(0, 3).map((v) => v[0]) },
      ],
      modelAnswer: s.writeModel,
      hintTip: s.tipSummary,
    },
  }));
}

