const SPECS_BY_LANG: Partial<Record<LanguageCode, RawUnitSpec[]>> = {
  en: EN_SPECS,
  es: ES_SPECS,
  fr: FR_SPECS,
  de: DE_SPECS,
  it: IT_SPECS,
  pt: PT_SPECS,
  ru: RU_SPECS,
  ja: JA_SPECS,
  zh: ZH_SPECS,
  ar: AR_SPECS,
  nl: NL_SPECS,
  af: AF_SPECS,
  sv: SV_SPECS,
  tr: TR_SPECS,
  he: HE_SPECS,
  nb: NB_SPECS,
  da: DA_SPECS,
};

const BUILT_CACHE = new Map<LanguageCode, { topics: Topic[]; vocab: VocabCard[] }>();

function getOrBuildForLang(lang: LanguageCode): { topics: Topic[]; vocab: VocabCard[] } {
  const cached = BUILT_CACHE.get(lang);
  if (cached) return cached;

  const specs = SPECS_BY_LANG[lang] ?? EN_SPECS;
  const topics: Topic[] = [];
  const vocab: VocabCard[] = [];

  for (const spec of specs) {
    const built = buildUnitAndVocab(lang, spec);
    topics.push(built.topic);
    vocab.push(...built.vocab);
  }

  const result = { topics, vocab };
  BUILT_CACHE.set(lang, result);
  return result;
}

export function getSpecializedTrackTopics(
  lang: LanguageCode,
  trackId?: SpecializedTrackId,
): Topic[] {
  const { topics } = getOrBuildForLang(lang);
  if (!trackId) return topics;
  return topics.filter((t) => t.id.startsWith(`spec-${lang}-${trackId}-`));
}

export function getSpecializedTrackVocab(lang: LanguageCode): VocabCard[] {
  return getOrBuildForLang(lang).vocab;
}
